package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"time"

	"github.com/liliang-cn/mcp-sqlite-server/database"
	"github.com/liliang-cn/mcp-sqlite-server/logger"
	"github.com/liliang-cn/mcp-sqlite-server/server"
)

// Version information
var (
	Version   = "1.0.0"
	BuildDate = "unknown"
)

func isDBFile(path string) bool {
	return strings.HasSuffix(strings.ToLower(path), ".db") ||
		strings.HasSuffix(strings.ToLower(path), ".sqlite") ||
		strings.HasSuffix(strings.ToLower(path), ".sqlite3") ||
		strings.HasSuffix(strings.ToLower(path), ".db3")
}

func runServer(srv *server.SQLiteServer) error {
	log := logger.GetLogger()

	// Create context with cancellation
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Setup signal handling for graceful shutdown
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM, syscall.SIGHUP)

	// Server error channel
	errChan := make(chan error, 1)

	// Start server in goroutine
	go func() {
		log.Info("Starting MCP SQLite server...")
		if err := srv.Start(); err != nil {
			errChan <- err
		}
	}()

	// Health check ticker - keeps the server alive and monitors health
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()

	// Start time for uptime tracking
	startTime := time.Now()
	log.Info("Server started successfully at %s", startTime.Format("2006-01-02 15:04:05"))

	// Main event loop
	for {
		select {
		case sig := <-sigChan:
			log.Info("Received signal: %v", sig)
			log.Info("Shutting down gracefully...")

			// Give server time to cleanup
			shutdownCtx, shutdownCancel := context.WithTimeout(ctx, 5*time.Second)
			defer shutdownCancel()

			// Close the server
			if err := srv.Close(); err != nil {
				log.Warning("Error during shutdown: %v", err)
			}

			select {
			case <-shutdownCtx.Done():
				log.Warning("Shutdown timeout exceeded, forcing exit")
			case <-time.After(100 * time.Millisecond):
				log.Info("Server shut down successfully")
			}

			return nil

		case err := <-errChan:
			if err != nil {
				log.Error("Server error: %v", err)
				log.Info("Attempting to restart in 5 seconds...")
				time.Sleep(5 * time.Second)

				// Try to restart
				go func() {
					log.Info("Restarting server...")
					if restartErr := srv.Start(); restartErr != nil {
						errChan <- fmt.Errorf("restart failed: %w", restartErr)
					}
				}()
			}

		case <-ticker.C:
			// Health check and status report
			uptime := time.Since(startTime)
			log.Debug("Server uptime: %s", uptime.Round(time.Second))

			// Check if server is still responsive
			if err := srv.HealthCheck(); err != nil {
				log.Warning("Health check failed: %v", err)
			} else {
				log.Debug("Health check passed")
			}

		case <-ctx.Done():
			log.Info("Context cancelled, shutting down")
			return ctx.Err()
		}
	}
}

func main() {
	// Define command line flags
	help := flag.Bool("help", false, "Show help message")
	h := flag.Bool("h", false, "Show help message (shorthand)")
	ver := flag.Bool("version", false, "Show version information")
	v := flag.Bool("v", false, "Show version information (shorthand)")
	logFile := flag.String("log", "", "Path to log file (optional, logs to stderr by default)")
	debug := flag.Bool("debug", false, "Enable debug logging")

	flag.Parse()

	// Handle help flag
	if *help || *h {
		fmt.Printf("Usage: mcp-sqlite-server [database-path-or-directory] [additional-directories...]\n")
		fmt.Println("Note: Database paths can be provided via:")
		fmt.Println("  1. Command-line arguments (shown above)")
		fmt.Println("  2. MCP roots protocol (if client supports it)")
		fmt.Println("At least one database or directory must be provided by EITHER method for the server to operate.")
		os.Exit(0)
	}

	// Handle version flag
	if *ver || *v {
		fmt.Printf("mcp-sqlite-server version %s\n", Version)
		if BuildDate != "" {
			fmt.Printf("Build date: %s\n", BuildDate)
		}
		os.Exit(0)
	}

	// Get remaining arguments after flags
	args := flag.Args()

	// Setup logging
	log := logger.GetLogger()
	if *debug {
		log.SetLevel(logger.DEBUG)
	}

	// Setup log file if specified
	if *logFile != "" {
		// Ensure log directory exists
		logDir := filepath.Dir(*logFile)
		if err := os.MkdirAll(logDir, 0755); err != nil {
			fmt.Fprintf(os.Stderr, "Failed to create log directory: %v\n", err)
		}

		if err := log.SetLogFile(*logFile); err != nil {
			fmt.Fprintf(os.Stderr, "Failed to open log file: %v\n", err)
		} else {
			defer log.Close()
			fmt.Fprintf(os.Stderr, "Logging to file: %s\n", *logFile)
		}
	}

	// Print startup message with timestamp
	log.Info("Secure MCP SQLite Server v%s starting...", Version)
	log.Info("Server will run continuously. Press Ctrl+C to stop.")

	// Check if arguments provided
	if len(args) == 0 {
		log.Info("Started without database paths - waiting for client to provide roots via MCP protocol")
		// Start server without initial database, waiting for roots
		srv := server.NewSQLiteServerWithoutDB()
		defer srv.Close()

		// Run server with signal handling
		if err := runServer(srv); err != nil {
			log.Fatal("Server error: %v", err)
		}
		return
	}

	// Use all arguments as directory/file paths
	allowedDirs := args
	log.Info("Starting with allowed directories: %v", allowedDirs)

	// Find the first directory with databases or database file
	var dbPath string
	var foundDatabases []string

	for _, path := range allowedDirs {
		stat, err := os.Stat(path)
		if err != nil {
			log.Warning("Cannot access path %s: %v", path, err)
			continue
		}

		if stat.IsDir() {
			// Check if directory has database files
			dbFiles, err := database.ListDatabaseFiles(path)
			if err != nil {
				log.Warning("Failed to list database files in directory %s: %v", path, err)
				continue
			}

			if len(dbFiles) > 0 {
				foundDatabases = append(foundDatabases, dbFiles...)
				if dbPath == "" {
					// Use the first database file found
					dbPath = dbFiles[0]
					log.Info("Found %d database file(s) in directory %s", len(dbFiles), path)
				}
			}
		} else if isDBFile(path) {
			// Direct database file path
			foundDatabases = append(foundDatabases, path)
			if dbPath == "" {
				dbPath = path
			}
		}
	}

	// If no databases found, start without initial database
	if dbPath == "" {
		log.Info("No database files found in specified paths. Server will wait for database selection via MCP protocol.")
		srv := server.NewSQLiteServerWithoutDB()
		srv.SetAllowedDirs(allowedDirs)
		defer srv.Close()

		// Run server with signal handling
		if err := runServer(srv); err != nil {
			log.Fatal("Server error: %v", err)
		}
		return
	}

	// Create and start server with allowed directories
	srv, err := server.NewSQLiteServerWithDirs(dbPath, allowedDirs)
	if err != nil {
		log.Fatal("Failed to create server: %v", err)
	}
	defer srv.Close()

	log.Info("Using database: %s", dbPath)
	if len(foundDatabases) > 1 {
		log.Info("Additional databases available: %d", len(foundDatabases)-1)
	}

	// Run server with signal handling
	if err := runServer(srv); err != nil {
		log.Fatal("Server error: %v", err)
	}
}
